import sys

def main():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    grid = [input().strip() for _ in range(H)]

    top = H
    bottom = -1
    left = W
    right = -1

    for i, row in enumerate(grid):
        l = row.find('#')
        if l != -1:
            if i < top:
                top = i
            if i > bottom:
                bottom = i
            if l < left:
                left = l
            r = row.rfind('#')
            if r > right:
                right = r

    for i in range(top, bottom + 1):
        if grid[i].find('.', left, right + 1) != -1:
            print("No")
            return

    print("Yes")

if __name__ == "__main__":
    main()
