import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    idx = 0
    n = data[idx]
    idx += 1

    dice = []
    for _ in range(n):
        k = data[idx]
        idx += 1
        counts = {}
        end = idx + k
        while idx < end:
            x = data[idx]
            idx += 1
            counts[x] = counts.get(x, 0) + 1
        dice.append((counts, k))

    dice.sort(key=lambda item: len(item[0]))

    ans = 0.0
    for i in range(n):
        ci, ki = dice[i]
        for j in range(i + 1, n):
            cj, kj = dice[j]
            dot = 0
            get = cj.get
            for x, c in ci.items():
                c2 = get(x)
                if c2 is not None:
                    dot += c * c2
            if dot:
                prob = dot / (ki * kj)
                if prob > ans:
                    ans = prob

    print(f"{ans:.15f}")

if __name__ == "__main__":
    main()
