import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    s = [ord(ch) - ord('a') for ch in S]
    states = 1 << N

    rows = []
    for mask in range(states):
        row = [0] * (N + 1)
        for i in range(1, N + 1):
            row[i] = row[i - 1] + ((mask >> (i - 1)) & 1)
        rows.append(row)

    trans = []
    for mask in range(states):
        row = rows[mask]
        cnt = {}
        for c in range(26):
            ndp = [0] * (N + 1)
            for i in range(1, N + 1):
                best = row[i]
                if ndp[i - 1] > best:
                    best = ndp[i - 1]
                if s[i - 1] == c:
                    cand = row[i - 1] + 1
                    if cand > best:
                        best = cand
                ndp[i] = best

            nxt = 0
            for i in range(1, N + 1):
                if ndp[i] != ndp[i - 1]:
                    nxt |= 1 << (i - 1)

            cnt[nxt] = cnt.get(nxt, 0) + 1
        trans.append(list(cnt.items()))

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, val in enumerate(dp):
            if val:
                for nxt, mult in trans[mask]:
                    ndp[nxt] += val * mult
        dp = [x % MOD for x in ndp]

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        if val:
            ans[mask.bit_count()] = (ans[mask.bit_count()] + val) % MOD

    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    main()
