import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M = data[0], data[1]
    A = [0] + data[2:2 + N]

    indeg = [0] * (N + 1)
    for i in range(1, N + 1):
        indeg[A[i]] += 1

    q = deque(i for i in range(1, N + 1) if indeg[i] == 0)
    in_cycle = [True] * (N + 1)
    size = [1] * (N + 1)

    while q:
        u = q.popleft()
        in_cycle[u] = False
        v = A[u]
        size[v] += size[u]
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)

    children = [[] for _ in range(N + 1)]
    for u in range(1, N + 1):
        if not in_cycle[u]:
            children[A[u]].append(u)

    for u in range(1, N + 1):
        if len(children[u]) > 1:
            children[u].sort(key=lambda x: size[x], reverse=True)

    sys.setrecursionlimit(1000000)
    M1 = M + 1
    mod = MOD
    base_G = list(range(M1))
    base_copy = base_G.copy
    rng = range(1, M1)

    def compute_tree(u, children=children, base_copy=base_copy, rng=rng, mod=mod):
        ch = children[u]
        if not ch:
            return base_copy()

        H = None
        for v in ch:
            arr = compute_tree(v)
            if H is None:
                H = arr
            else:
                for i in rng:
                    H[i] = (H[i] * arr[i]) % mod
            del arr

        s = 0
        for i in rng:
            s += H[i]
            if s >= mod:
                s -= mod
            H[i] = s
        H[0] = 0
        return H

    def compute_cycle_factor(u, children=children, rng=rng, mod=mod):
        ch = children[u]
        if not ch:
            return None

        H = None
        for v in ch:
            arr = compute_tree(v)
            if H is None:
                H = arr
            else:
                for i in rng:
                    H[i] = (H[i] * arr[i]) % mod
            del arr
        return H

    seen = [False] * (N + 1)
    ans = 1

    for u in range(1, N + 1):
        if in_cycle[u] and not seen[u]:
            comp = []
            cur = u
            while not seen[cur]:
                seen[cur] = True
                comp.append(cur)
                cur = A[cur]

            prod = None
            for node in comp:
                H = compute_cycle_factor(node)
                if H is None:
                    continue
                if prod is None:
                    prod = H
                else:
                    for i in rng:
                        prod[i] = (prod[i] * H[i]) % mod
                del H

            if prod is None:
                total = M % mod
            else:
                total = sum(prod[1:]) % mod

            ans = (ans * total) % mod

    print(ans)

if __name__ == "__main__":
    main()
